import sys

def find_dominant_piranha(n, a):
    for i in range(1, n - 1):
        if a[i] > a[i - 1] and a[i] > a[i + 1]:
            return i + 1
    if a[0] > a[1]:
        return 1
    if a[-1] > a[-2]:
        return n
    return -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        a = list(map(int, data[index:index + n]))
        index += n
        result = find_dominant_piranha(n, a)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
